CREATE TABLE IF NOT EXISTS ifund_transfer.source_inventory (origin_project_ref text NOT NULL DEFAULT 'tzehxfikoslihnclhxuz', source_relation text NOT NULL, entity_type text NOT NULL, observed_source_rows bigint NOT NULL CHECK (observed_source_rows >= 0), staged_target_rows bigint NOT NULL DEFAULT 0 CHECK (staged_target_rows >= 0), source_export_verified boolean NOT NULL DEFAULT false CHECK (source_export_verified = false), notes text NOT NULL DEFAULT '', observed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(origin_project_ref,source_relation,entity_type)); ALTER TABLE ifund_transfer.source_inventory ENABLE ROW LEVEL SECURITY; REVOKE ALL ON ifund_transfer.source_inventory FROM PUBLIC, anon, authenticated; GRANT SELECT,INSERT,UPDATE ON ifund_transfer.source_inventory TO service_role;